"""Tessaro feeds - PinStore and fingerprint utilities."""

import hashlib
import json
import os

# Pinned fingerprints for known hosts
PINNED_HOSTS = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Stores pinned certificate fingerprints for hosts."""

    def __init__(self, pins: dict):
        self._pins = pins

    @classmethod
    def load(cls):
        """Load the pin store from the default configuration."""
        return cls(PINNED_HOSTS)

    def matches(self, host: str, fingerprint: str) -> bool:
        """Check if the fingerprint matches the pinned value for the host."""
        return self._pins.get(host) == fingerprint
